export type VideoSegment={start:number;end:number;speed?:number};
export type TimelineSegment={segment:VideoSegment;index:number;start:number;end:number};
export type ProjectedRange={index:number;start:number;end:number;sourceStart:number;sourceEnd:number;speed:number;clipStart:number;clipEnd:number};
export const MIN_CLIP:number;
export const MAX_CLIPS:number;
export function segmentSpeed(segment:VideoSegment):number;
export function validVideoRange(start:number,end:number,duration:number):boolean;
export function validSegments(segments:VideoSegment[],duration:number):boolean;
export function videoTimeLabel(seconds:number):string;
export function splitSegment(segments:VideoSegment[],time:number):VideoSegment[];
export function trimSegment(segments:VideoSegment[],index:number,edge:'start'|'end',value:number,duration:number):VideoSegment[];
export function moveSegment(segments:VideoSegment[],from:number,to:number):VideoSegment[];
export function timelineSegments(segments:VideoSegment[]):TimelineSegment[];
export function timelineDuration(segments:VideoSegment[]):number;
export function nextPlayableTime(segments:VideoSegment[],time:number):number|null;
export function sourceAtOutput(segments:VideoSegment[],time:number):{index:number;time:number}|null;
export function outputTime(segments:VideoSegment[],sourceTime:number,indexHint?:number):number;
export function deletedRanges(segments:VideoSegment[],duration:number):VideoSegment[];
export function projectTimedRange(segments:VideoSegment[],start:number,end:number):ProjectedRange[];
